model_options = [
    {"name": "small-general", "dimensions": 384, "latency_ms": 12, "quality_score": 0.78},
    {"name": "large-general", "dimensions": 1536, "latency_ms": 45, "quality_score": 0.91},
    {"name": "domain-legal", "dimensions": 768, "latency_ms": 20, "quality_score": 0.88},
]

def score_model_for_pipeline(model, priority):
    # weighs the model size and quality tradeoff
    if priority == "speed":
        return -model["latency_ms"]
    if priority == "quality":
        return model["quality_score"]
    # balanced priority weighs both
    return model["quality_score"] - (model["latency_ms"] / 1000)

for priority in ["speed", "quality", "balanced"]:
    ranked = sorted(model_options, key=lambda m: score_model_for_pipeline(m, priority), reverse=True)
    best = ranked[0]
    print(f"Priority '{priority}': best model is {best['name']!r}")
    print(f"  dimensions={best['dimensions']}, latency={best['latency_ms']}ms, quality={best['quality_score']}\n")
